25	int bt_reject_conn(struct bt_dev *hdev, const bt_addr_t *bdaddr, uint8_t reason)
26	{
27		struct bt_hci_cp_reject_conn_req *cp;
28		struct net_buf *buf;
29		int err;
30	
31		buf = bt_hci_cmd_create(BT_HCI_OP_REJECT_CONN_REQ, sizeof(*cp));
32		if (!buf) {
33			return -ENOBUFS;
34		}
35	
36		cp = net_buf_add(buf, sizeof(*cp));
37		bt_addr_copy(&cp->bdaddr, bdaddr);
38		cp->reason = reason;
39	
40		err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_REJECT_CONN_REQ, buf, NULL);
41		if (err) {
42			return err;
43		}
44	
45		return 0;
46	}
