48	int bt_accept_conn(struct bt_dev *hdev, const bt_addr_t *bdaddr)
49	{
50		struct bt_hci_cp_accept_conn_req *cp;
51		struct net_buf *buf;
52		int err;
53	
54		buf = bt_hci_cmd_create(BT_HCI_OP_ACCEPT_CONN_REQ, sizeof(*cp));
55		if (!buf) {
56			return -ENOBUFS;
57		}
58	
59		cp = net_buf_add(buf, sizeof(*cp));
60		bt_addr_copy(&cp->bdaddr, bdaddr);
61		cp->role = BT_HCI_ROLE_PERIPHERAL;
62	
63		err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_ACCEPT_CONN_REQ, buf, NULL);
64		if (err) {
65			return err;
66		}
67	
68		return 0;
69	}
