71	void bt_hci_conn_req(struct bt_dev *hdev, struct net_buf *buf)
72	{
73		struct bt_hci_evt_conn_request *evt = (void *)buf->data;
74		struct bt_conn *conn;
75	
76		LOG_DBG("conn req from %s, type 0x%02x", bt_addr_str(&evt->bdaddr), evt->link_type);
77	
78		if (evt->link_type != BT_HCI_ACL) {
79			uint8_t err;
80	
81			err = bt_esco_conn_req(hdev, evt);
82			if (err != BT_HCI_ERR_SUCCESS) {
83				bt_reject_conn(hdev, &evt->bdaddr, err);
84			}
85			return;
86		}
87	
88		conn = bt_conn_add_br(hdev, &evt->bdaddr);
89		if (!conn) {
90			bt_reject_conn(hdev, &evt->bdaddr, BT_HCI_ERR_INSUFFICIENT_RESOURCES);
91			return;
92		}
93	
94	#if defined(CONFIG_BT_CONN_REQ_AUTO_HANDLE)
95		if (bt_accept_conn(hdev, &evt->bdaddr)) {
96			LOG_ERR("Error accepting connection from %s",
97			       bt_addr_str(&evt->bdaddr));
98			bt_conn_unref(conn);
99			return;
100		}
101	
102		conn->role = BT_HCI_ROLE_PERIPHERAL;
103		bt_conn_set_state(conn, BT_CONN_INITIATING);
104		bt_conn_unref(conn);
105	#else
106		bt_conn_notify_connect_req(conn, evt->link_type, evt->dev_class);
107	#endif /* CONFIG_BT_CONN_REQ_AUTO_HANDLE */
108	}
