193	void bt_hci_synchronous_conn_complete(struct bt_dev *hdev, struct net_buf *buf)
194	{
195		struct bt_hci_evt_sync_conn_complete *evt = (void *)buf->data;
196		struct bt_conn *sco_conn;
197		uint16_t handle = sys_le16_to_cpu(evt->handle);
198	
199		LOG_DBG("status 0x%02x, handle %u, type 0x%02x", evt->status, handle, evt->link_type);
200	
201		sco_conn = bt_conn_lookup_addr_sco(hdev, &evt->bdaddr);
202		if (!sco_conn) {
203			LOG_ERR("Unable to find conn for %s", bt_addr_str(&evt->bdaddr));
204			return;
205		}
206	
207		if (evt->status) {
208			sco_conn->err = evt->status;
209			bt_conn_set_state(sco_conn, BT_CONN_DISCONNECTED);
210			bt_conn_unref(sco_conn);
211			return;
212		}
213	
214		sco_conn->handle = handle;
215		sco_conn->sco.air_mode = evt->air_mode;
216	
217		if (sco_conn->sco.link_type != evt->link_type) {
218			LOG_WRN("link type mismatch %u != %u", sco_conn->sco.link_type, evt->link_type);
219			sco_conn->sco.link_type = evt->link_type;
220		}
221		bt_conn_set_state(sco_conn, BT_CONN_CONNECTED);
222		bt_conn_unref(sco_conn);
223	}
