297	static int request_name(struct bt_dev *hdev, const bt_addr_t *addr,
298				 uint8_t pscan, uint16_t offset)
299	{
300		struct bt_hci_cp_remote_name_request *cp;
301		struct net_buf *buf;
302	
303		buf = bt_hci_cmd_create(BT_HCI_OP_REMOTE_NAME_REQUEST, sizeof(*cp));
304		if (!buf) {
305			return -ENOBUFS;
306		}
307	
308		cp = net_buf_add(buf, sizeof(*cp));
309	
310		bt_addr_copy(&cp->bdaddr, addr);
311		cp->pscan_rep_mode = pscan;
312		cp->reserved = 0x00; /* reserved, should be set to 0x00 */
313		cp->clock_offset = offset;
314	
315		return bt_hci_cmd_send_sync(hdev, BT_HCI_OP_REMOTE_NAME_REQUEST, buf, NULL);
316	}
