318	#define EIR_SHORT_NAME    0x08
319	#define EIR_COMPLETE_NAME 0x09
320	
321	static bool eir_has_name(const uint8_t *eir)
322	{
323		int len = 240;
324	
325		while (len) {
326			if (len < 2) {
327				break;
328			}
329	
330			/* Look for early termination */
331			if (!eir[0]) {
332				break;
333			}
334	
335			/* Check if field length is correct */
336			if (eir[0] > len - 1) {
337				break;
338			}
339	
340			switch (eir[1]) {
341			case EIR_SHORT_NAME:
342			case EIR_COMPLETE_NAME:
343				if (eir[0] > 1) {
344					return true;
345				}
346				break;
347			default:
348				break;
349			}
350	
351			/* Parse next AD Structure */
352			len -= eir[0] + 1;
353			eir += eir[0] + 1;
354		}
355	
356		return false;
357	}
