359	void bt_br_discovery_reset(struct bt_dev *hdev)
360	{
361		hdev->discovery_results = NULL;
362		hdev->discovery_results_size = 0;
363		hdev->discovery_results_count = 0;
364	}
365	
366	static void report_discovery_results(struct bt_dev *hdev)
367	{
368		bool resolving_names = false;
369		int i;
370		struct bt_br_discovery_cb *listener, *next;
371	
372		for (i = 0; i < hdev->discovery_results_count; i++) {
373			struct bt_br_discovery_priv *priv;
374	
375			priv = &hdev->discovery_results[i]._priv;
376	
377			if (eir_has_name(hdev->discovery_results[i].eir)) {
378				continue;
379			}
380	
381			if (request_name(hdev, &hdev->discovery_results[i].addr, priv->pscan_rep_mode,
382					 priv->clock_offset)) {
383				continue;
384			}
385	
386			priv->resolving = true;
387			resolving_names = true;
388		}
389	
390		if (resolving_names) {
391			return;
392		}
393	
394		atomic_clear_bit(hdev->flags, BT_DEV_INQUIRY);
395	
396		SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&hdev->discovery_cbs, listener, next, node) {
397			if (listener->timeout) {
398				listener->timeout(hdev->discovery_results, hdev->discovery_results_count);
399			}
400		}
401	
402		bt_br_discovery_reset(hdev);
403	}
