416	static struct bt_br_discovery_result *get_result_slot(struct bt_dev *hdev,
417										 const bt_addr_t *addr, int8_t rssi)
418	{
419		struct bt_br_discovery_result *result = NULL;
420		size_t i;
421	
422		/* check if already present in results */
423		for (i = 0; i < hdev->discovery_results_count; i++) {
424			if (bt_addr_eq(addr, &hdev->discovery_results[i].addr)) {
425				return &hdev->discovery_results[i];
426			}
427		}
428	
429		/* Pick a new slot (if available) */
430		if (hdev->discovery_results_count < hdev->discovery_results_size) {
431			bt_addr_copy(&hdev->discovery_results[hdev->discovery_results_count].addr, addr);
432			return &hdev->discovery_results[hdev->discovery_results_count++];
433		}
434	
435		/* ignore if invalid RSSI */
436		if (rssi == 0xff) {
437			return NULL;
438		}
439	
440		/*
441		 * Pick slot with smallest RSSI that is smaller then passed RSSI
442		 * TODO handle TX if present
443		 */
444		for (i = 0; i < hdev->discovery_results_size; i++) {
445			if (hdev->discovery_results[i].rssi > rssi) {
446				continue;
447			}
448	
449			if (!result || result->rssi > hdev->discovery_results[i].rssi) {
450				result = &hdev->discovery_results[i];
451			}
452		}
453	
454		if (result) {
455			LOG_DBG("Reusing slot (old %s rssi %d dBm)", bt_addr_str(&result->addr),
456				result->rssi);
457	
458			bt_addr_copy(&result->addr, addr);
459		}
460	
461		return result;
462	}
