464	static struct bt_br_discovery_result *find_discovery_result(struct bt_dev *hdev, const bt_addr_t *addr)
465	{
466		size_t i;
467	
468		/* check if already present in results */
469		for (i = 0; i < hdev->discovery_results_count; i++) {
470			if (!bt_addr_cmp(addr, &hdev->discovery_results[i].addr)) {
471				return &hdev->discovery_results[i];
472			}
473		}
474	
475		return NULL;
476	}
