478	void bt_hci_inquiry_result_with_rssi(struct bt_dev *hdev, struct net_buf *buf)
479	{
480		uint8_t num_reports = net_buf_pull_u8(buf);
481	
482		if (!atomic_test_bit(hdev->flags, BT_DEV_INQUIRY)) {
483			return;
484		}
485	
486		LOG_DBG("number of results: %u", num_reports);
487	
488		while (num_reports--) {
489			struct bt_hci_evt_inquiry_result_with_rssi *evt;
490			struct bt_br_discovery_result *result;
491			struct bt_br_discovery_priv *priv;
492			struct bt_br_discovery_cb *listener, *next;
493	
494			if (buf->len < sizeof(*evt)) {
495				LOG_ERR("Unexpected end to buffer");
496				return;
497			}
498	
499			evt = net_buf_pull_mem(buf, sizeof(*evt));
500			LOG_DBG("%s rssi %d dBm", bt_addr_str(&evt->addr), evt->rssi);
501	
502			result = get_result_slot(hdev, &evt->addr, evt->rssi);
503			if (!result) {
504				return;
505			}
506	
507			priv = &result->_priv;
508			priv->pscan_rep_mode = evt->pscan_rep_mode;
509			priv->clock_offset = evt->clock_offset;
510	
511			memcpy(result->cod, evt->cod, 3);
512			result->rssi = evt->rssi;
513	
514			/* we could reuse slot so make sure EIR is cleared */
515			(void)memset(result->eir, 0, sizeof(result->eir));
516	
517			SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&hdev->discovery_cbs, listener, next, node) {
518				if (listener->recv) {
519					listener->recv(result);
520				}
521			}
522		}
523	}
