558	void bt_hci_remote_name_request_complete(struct bt_dev *hdev, struct net_buf *buf)
559	{
560		struct bt_hci_evt_remote_name_req_complete *evt = (void *)buf->data;
561		struct bt_br_discovery_result *result;
562		struct bt_br_discovery_priv *priv;
563		int eir_len = 240;
564		uint8_t *eir;
565		int i;
566		struct bt_br_discovery_cb *listener, *next;
567	
568		if (hdev->rnr_cb.cb && !bt_addr_cmp(&evt->bdaddr, &hdev->rnr_cb.addr)) {
569			LOG_DBG("status 0x%02x", evt->status);
570			hdev->rnr_cb.cb(&evt->bdaddr, evt->name, evt->status);
571			memset(&hdev->rnr_cb, 0, sizeof(hdev->rnr_cb));
572		}
573	
574		result = get_result_slot(hdev, &evt->bdaddr, 0xff);
575		if (!result) {
576			return;
577		}
578	
579		priv = &result->_priv;
580		priv->resolving = false;
581	
582		if (evt->status) {
583			goto check_names;
584		}
585	
586		eir = result->eir;
587	
588		while (eir_len) {
589			if (eir_len < 2) {
590				break;
591			}
592	
593			/* Look for early termination */
594			if (!eir[0]) {
595				size_t name_len;
596	
597				eir_len -= 2;
598	
599				/* name is null terminated */
600				name_len = strlen((const char *)evt->name);
601	
602				if (name_len > eir_len) {
603					eir[0] = eir_len + 1;
604					eir[1] = EIR_SHORT_NAME;
605				} else {
606					eir[0] = name_len + 1;
607					eir[1] = EIR_SHORT_NAME;
608				}
609	
610				memcpy(&eir[2], evt->name, eir[0] - 1);
611	
612				break;
613			}
614	
615			/* Check if field length is correct */
616			if (eir[0] > eir_len - 1) {
617				break;
618			}
619	
620			/* next EIR Structure */
621			eir_len -= eir[0] + 1;
622			eir += eir[0] + 1;
623		}
624	
625		SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&hdev->discovery_cbs, listener, next, node) {
626			if (listener->recv) {
627				listener->recv(result);
628			}
629		}
630	
631	check_names:
632		/* if still waiting for names */
633		for (i = 0; i < hdev->discovery_results_count; i++) {
634			struct bt_br_discovery_priv *dpriv;
635	
636			dpriv = &hdev->discovery_results[i]._priv;
637	
638			if (dpriv->resolving) {
639				return;
640			}
641		}
642	
643		/* all names resolved, report discovery results */
644		atomic_clear_bit(hdev->flags, BT_DEV_INQUIRY);
645	
646		SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&hdev->discovery_cbs, listener, next, node) {
647			if (listener->timeout) {
648				listener->timeout(hdev->discovery_results, hdev->discovery_results_count);
649			}
650		}
651	}
