653	void bt_hci_read_remote_features_complete(struct bt_dev *hdev, struct net_buf *buf)
654	{
655		struct bt_hci_evt_remote_features *evt = (void *)buf->data;
656		uint16_t handle = sys_le16_to_cpu(evt->handle);
657		struct bt_hci_cp_read_remote_ext_features *cp;
658		struct bt_conn *conn;
659	
660		LOG_DBG("status 0x%02x handle %u", evt->status, handle);
661	
662		conn = bt_conn_lookup_handle(hdev, handle, BT_CONN_TYPE_BR);
663		if (!conn) {
664			LOG_ERR("Can't find conn for handle %u", handle);
665			return;
666		}
667	
668		if (evt->status) {
669			goto done;
670		}
671	
672		memcpy(conn->br.features[0], evt->features, sizeof(evt->features));
673	
674		if (!BT_FEAT_EXT_FEATURES(conn->br.features)) {
675			goto done;
676		}
677	
678		buf = bt_hci_cmd_create(BT_HCI_OP_READ_REMOTE_EXT_FEATURES, sizeof(*cp));
679		if (!buf) {
680			goto done;
681		}
682	
683		/* Read remote host features (page 1) */
684		cp = net_buf_add(buf, sizeof(*cp));
685		cp->handle = evt->handle;
686		cp->page = 0x01;
687	
688		bt_hci_cmd_send_sync(hdev, BT_HCI_OP_READ_REMOTE_EXT_FEATURES, buf, NULL);
689		bt_conn_unref(conn);
690		return;
691	
692	done:
693		br_report_connection_state(conn);
694		bt_conn_unref(conn);
695	}
