1026	static bool valid_br_discov_param(const struct bt_br_discovery_param *param, size_t num_results)
1027	{
1028		if (!num_results || num_results > 255) {
1029			return false;
1030		}
1031	
1032		if (!param->length || param->length > 0x30) {
1033			return false;
1034		}
1035	
1036		return true;
1037	}
