1039	int bt_br_discovery_start_mc(uint8_t dev_id, const struct bt_br_discovery_param *param,
1040				  struct bt_br_discovery_result *results, size_t cnt)
1041	{
1042		int err;
1043		struct bt_dev *hdev;
1044	
1045		LOG_DBG("");
1046	
1047		hdev = bt_dev_get(dev_id);
1048		if (!hdev) {
1049			return -ENODEV;
1050		}
1051	
1052		if (!valid_br_discov_param(param, cnt)) {
1053			return -EINVAL;
1054		}
1055	
1056		if (atomic_test_bit(hdev->flags, BT_DEV_INQUIRY)) {
1057			return -EALREADY;
1058		}
1059	
1060		err = br_start_inquiry(hdev, param);
1061		if (err) {
1062			return err;
1063		}
1064	
1065		atomic_set_bit(hdev->flags, BT_DEV_INQUIRY);
1066	
1067		(void)memset(results, 0, sizeof(*results) * cnt);
1068	
1069		hdev->discovery_results = results;
1070		hdev->discovery_results_size = cnt;
1071		hdev->discovery_results_count = 0;
1072	
1073		return 0;
1074	}
1075	
1076	int bt_br_discovery_stop_mc(uint8_t dev_id)
1077	{
1078		int err;
1079		int i;
1080		struct bt_dev *hdev;
1081	
1082		LOG_DBG("");
1083	
1084		hdev = bt_dev_get(dev_id);
1085		if (!hdev) {
1086			return -ENODEV;
1087		}
1088	
1089		if (!atomic_test_bit(hdev->flags, BT_DEV_INQUIRY)) {
1090			return -EALREADY;
1091		}
1092	
1093		err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_INQUIRY_CANCEL, NULL, NULL);
1094		if (err) {
1095			LOG_ERR("Failed to cancel inquiry (err %d)", err);
1096		}
1097	
1098		for (i = 0; i < hdev->discovery_results_count; i++) {
1099			struct bt_br_discovery_priv *priv;
1100			struct bt_hci_cp_remote_name_cancel *cp;
1101			struct net_buf *buf;
1102	
1103			priv = &hdev->discovery_results[i]._priv;
1104	
1105			if (!priv->resolving) {
1106				continue;
1107			}
1108	
1109			buf = bt_hci_cmd_create(BT_HCI_OP_REMOTE_NAME_CANCEL, sizeof(*cp));
1110			if (!buf) {
1111				continue;
1112			}
1113	
1114			cp = net_buf_add(buf, sizeof(*cp));
1115			bt_addr_copy(&cp->bdaddr, &hdev->discovery_results[i].addr);
1116	
1117			bt_hci_cmd_send_sync(hdev, BT_HCI_OP_REMOTE_NAME_CANCEL, buf, NULL);
1118		}
1119	
1120		atomic_clear_bit(hdev->flags, BT_DEV_INQUIRY);
1121	
1122		hdev->discovery_results = NULL;
1123		hdev->discovery_results_size = 0;
1124		hdev->discovery_results_count = 0;
1125	
1126		return err;
1127	}
