1207			if (atomic_test_bit(hdev->flags, BT_DEV_ISCAN)) {
1208				return -EALREADY;
1209			}
1210	
1211			if (!atomic_test_bit(hdev->flags, BT_DEV_PSCAN)) {
1212				return -EPERM;
1213			}
1214	
1215			return write_scan_enable(hdev, BT_BREDR_SCAN_INQUIRY | BT_BREDR_SCAN_PAGE);
1216		} else {
1217			if (!atomic_test_bit(hdev->flags, BT_DEV_ISCAN)) {
1218				return -EALREADY;
1219			}
1220	
1221			return write_scan_enable(hdev, BT_BREDR_SCAN_PAGE);
1222		}
1223	}
