1442	int bt_br_write_ext_inq_response_mc(uint8_t dev_id, uint8_t fec_required)
1443	{
1444		struct net_buf *buf;
1445		struct bt_hci_cp_write_extended_inquiry_response *cp;
1446		size_t name_len, eir_len = 240;
1447		uint8_t type;
1448		uint8_t *p;
1449		struct bt_dev *hdev;
1450	
1451		hdev = bt_dev_get(dev_id);
1452		if (!hdev) {
1453			return -ENODEV;
1454		}
1455	 
1456		if (!BT_FEAT_EIR(hdev->features)) {
1457			return -ENOTSUP;
1458		}
1459	
1460		buf = bt_hci_cmd_create(BT_HCI_OP_WRITE_EXTENDED_INQUIRY_RESPONSE, sizeof(*cp));
1461		if (!buf) {
1462			return -ENOBUFS;
1463		}
1464	
1465		net_buf_add_u8(buf, fec_required);
1466	
1467		/* Fill in EIR data (Name) */
1468		eir_len -= 2;
1469		name_len = strlen(hdev->name);
1470		if (name_len > eir_len) {
1471			name_len = eir_len;
1472			type = EIR_SHORT_NAME;
1473			eir_len = 0;
1474		} else {
1475			type = EIR_COMPLETE_NAME;
1476			eir_len -= name_len;
1477		}
1478	
1479		net_buf_add_u8(buf, name_len + 1);
1480		net_buf_add_u8(buf, type);
1481		net_buf_add_mem(buf, hdev->name, name_len);
1482	
1483		/* TODO: Fill in EIR data (COD) */
1484		/* TODO: Fill in EIR data (UUID) */
1485		/* TODO: Fill in EIR data (Flags) */
1486		/* TODO: Fill in EIR data (Manufacturer Specific Data) */
1487		/* TODO: Fill in EIR data (TX Power) */
1488	
1489		p = net_buf_add(buf, eir_len);
1490		memset(p, 0, eir_len);
1491	
1492		return bt_hci_cmd_send_sync(hdev, BT_HCI_OP_WRITE_EXTENDED_INQUIRY_RESPONSE, buf, NULL);
