1495	int bt_br_remote_name_request_mc(uint8_t dev_id, const bt_addr_t *bdaddr, bt_br_remote_name_req_cb_t cb)
1496	{
1497		struct bt_br_discovery_result *result;
1498		struct bt_br_discovery_priv *priv;
1499		struct bt_dev *hdev;
1500		int err;
1501	
1502		hdev = bt_dev_get(dev_id);
1503		if (!hdev) {
1504			return -ENODEV;
1505		}
1506	
1507		if (hdev->rnr_cb.cb) {
1508			return -EBUSY;
1509		}
1510	
1511		/* save remote name request control block */
1512		hdev->rnr_cb.cb = cb;
1513		bt_addr_copy(&hdev->rnr_cb.addr, bdaddr);
1514	
1515		/* check if we have a cached result */
1516		result = find_discovery_result(hdev, bdaddr);
1517		if (result) {
1518			/* check is resolving, just return if resolving */
1519			priv = (struct bt_br_discovery_priv *)&result->_priv;
1520			if (priv->resolving) {
1521				return 0;
1522			}
1523	
1524			priv->resolving = 1;
1525			err = request_name(hdev, bdaddr, priv->pscan_rep_mode, priv->clock_offset);
1526		} else {
1527			/* start discovery to resolve name by default param */
1528			err = request_name(hdev, bdaddr, BT_HCI_PAGE_SCAN_REP_MODE_R2, 0);
1529		}
1530	
1531		if (err) {
1532			LOG_ERR("Unable to request name for %s (err %d)", bt_addr_str(bdaddr), err);
1533			hdev->rnr_cb.cb(bdaddr, NULL, BT_HCI_ERR_UNSPECIFIED);
1534	
1535			/* clear control block */
1536			memset(&hdev->rnr_cb, 0, sizeof(hdev->rnr_cb));
1537			return err;
1538		}
1539	
1540		return 0;
1541	}
