1569			return -ENOTSUP;
1570		}
1571	
1572		hdev = bt_dev_get(dev_id);
1573		if (!hdev) {
1574			return -ENODEV;
1575		}
1576	
1577		/* Disconnect acl connection if connection is existed */
1578		conn = bt_conn_lookup_addr_br_mc(dev_id, bdaddr);
1579		if (conn) {
1580			bt_conn_disconnect(conn, BT_HCI_ERR_REMOTE_USER_TERM_CONN);
1581			bt_conn_unref(conn);
1582		}
1583	
1584		/* Delete stored link key from settings */
1585		bt_keys_link_key_clear_addr(hdev, bdaddr);
1586	
1587		/* Delete stored link key from controller */
1588		bt_br_delete_stored_link_key(hdev, bdaddr, false);
1589	
1590		addr.type = BT_ADDR_LE_PUBLIC;
1591		memcpy(&addr, bdaddr, sizeof(addr));
1592	
1593		SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&hdev->bt_auth_info_cbs, listener,
1594						  next, node) {
1595			if (listener->bond_deleted) {
1596				listener->bond_deleted(0, &addr);
1597			}
1598		}
1599	
1600		return 0;
1601	}
