110	static bool br_sufficient_key_size(struct bt_conn *conn)
111	{
112		struct bt_hci_cp_read_encryption_key_size *cp;
113		struct bt_hci_rp_read_encryption_key_size *rp;
114		struct net_buf *buf, *rsp;
115		uint8_t key_size;
116		int err;
117	
118		buf = bt_hci_cmd_create(BT_HCI_OP_READ_ENCRYPTION_KEY_SIZE, sizeof(*cp));
119		if (!buf) {
120			LOG_ERR("Failed to allocate command buffer");
121			return false;
122		}
123	
124		cp = net_buf_add(buf, sizeof(*cp));
125		cp->handle = sys_cpu_to_le16(conn->handle);
126	
127		err = bt_hci_cmd_send_sync(conn->hdev, BT_HCI_OP_READ_ENCRYPTION_KEY_SIZE, buf, &rsp);
128		if (err) {
129			LOG_ERR("Failed to read encryption key size (err %d)", err);
130			return false;
131		}
132	
133		if (rsp->len < sizeof(*rp)) {
134			LOG_ERR("Too small command complete for encryption key size");
135			net_buf_unref(rsp);
136			return false;
137		}
138	
139		rp = (void *)rsp->data;
140		key_size = rp->key_size;
141		net_buf_unref(rsp);
142	
143		if (conn->br.link_key) {
144			conn->br.link_key->enc_key_size = key_size;
145		}
146	
147		LOG_DBG("Encryption key size is %u", key_size);
148	
149		if (conn->sec_level == BT_SECURITY_L4) {
150			return key_size == BT_HCI_ENCRYPTION_KEY_SIZE_MAX;
151		}
152	
153		return key_size >= CONFIG_BT_BR_MIN_ENC_KEY_SIZE;
154	}
155	
156	bool bt_br_update_sec_level(struct bt_conn *conn)
157	{
158		if (!conn->encrypt) {
159			conn->sec_level = BT_SECURITY_L1;
160			return true;
161		}
162	
163		if (conn->br.link_key) {
164			if (conn->br.link_key->flags & BT_LINK_KEY_AUTHENTICATED) {
165				if (conn->encrypt == BT_HCI_ENCRYPTION_ON_BR_AES_CCM) {
166					conn->sec_level = BT_SECURITY_L4;
167				} else {
168					conn->sec_level = BT_SECURITY_L3;
169				}
170			} else {
171				conn->sec_level = BT_SECURITY_L2;
172			}
173		} else {
174			LOG_WRN("No BR/EDR link key found");
175			conn->sec_level = BT_SECURITY_L2;
176		}
177	
178		if (!br_sufficient_key_size(conn)) {
179			LOG_ERR("Encryption key size is not sufficient");
180			bt_conn_disconnect(conn, BT_HCI_ERR_AUTH_FAIL);
181			return false;
182		}
183	
184		if (conn->required_sec_level > conn->sec_level) {
185			LOG_ERR("Failed to set required security level");
186			bt_conn_disconnect(conn, BT_HCI_ERR_AUTH_FAIL);
187			return false;
188		}
189	
190		return true;
191	}
