225	static void br_report_connection_state(struct bt_conn *conn)
226	{
227		bt_conn_notify_connected(conn);
228	
229		if (atomic_test_bit(conn->flags, BT_CONN_BR_PAIRING_CONN_PEND)) {
230			atomic_clear_bit(conn->flags, BT_CONN_BR_PAIRING_CONN_PEND);
231			if (bt_conn_set_security(conn, conn->attempt_sec_level)) {
232				bt_conn_security_changed(conn, BT_HCI_ERR_AUTH_FAIL,
233							BT_SECURITY_ERR_AUTH_FAIL);
234				bt_conn_disconnect(conn, BT_HCI_ERR_AUTH_FAIL);
235			}
236		}
237	}
