239	void bt_hci_conn_complete(struct bt_dev *hdev, struct net_buf *buf)
240	{
241		struct bt_hci_evt_conn_complete *evt = (void *)buf->data;
242		struct bt_conn *conn;
243		struct bt_hci_cp_read_remote_features *cp;
244		uint16_t handle = sys_le16_to_cpu(evt->handle);
245	
246		LOG_DBG("status 0x%02x, handle %u, type 0x%02x", evt->status, handle, evt->link_type);
247	
248		conn = bt_conn_lookup_addr_br_mc(hdev->dev_id, &evt->bdaddr);
249		if (!conn) {
250			LOG_ERR("Unable to find conn for %s", bt_addr_str(&evt->bdaddr));
251			return;
252		}
253	
254		if (evt->status) {
255			if (atomic_test_bit(conn->flags, BT_CONN_BR_PAIRING_CONN_PEND)) {
256				atomic_clear_bit(conn->flags, BT_CONN_BR_PAIRING_CONN_PEND);
257				bt_conn_security_changed(conn, evt->status,
258							bt_security_err_get(evt->status));
259			}
260	
261			conn->err = evt->status;
262			bt_conn_set_state(conn, BT_CONN_DISCONNECTED);
263			bt_conn_unref(conn);
264			return;
265		}
266	
267		conn->handle = handle;
268		conn->err = 0U;
269		conn->encrypt = evt->encr_enabled;
270	
271		if (!bt_br_update_sec_level(conn)) {
272			bt_conn_unref(conn);
273			return;
274		}
275	
276		bt_conn_set_state(conn, BT_CONN_CONNECTED);
277	
278		atomic_set_bit_to(conn->flags, BT_CONN_BR_BONDABLE, bt_get_bondable_mc(hdev->dev_id));
279	
280		bt_conn_connected(conn);
281	
282		buf = bt_hci_cmd_create(BT_HCI_OP_READ_REMOTE_FEATURES, sizeof(*cp));
283		if (!buf) {
284			br_report_connection_state(conn);
285			bt_conn_unref(conn);
286			return;
287		}
288	
289		bt_conn_unref(conn);
290	
291		cp = net_buf_add(buf, sizeof(*cp));
292		cp->handle = evt->handle;
293	
294		bt_hci_cmd_send_sync(hdev, BT_HCI_OP_READ_REMOTE_FEATURES, buf, NULL);
295	}
