297	static int request_name(struct bt_dev *hdev, const bt_addr_t *addr,
298				 uint8_t pscan, uint16_t offset)
299	{
300		struct bt_hci_cp_remote_name_request *cp;
301		struct net_buf *buf;
302	
303		buf = bt_hci_cmd_create(BT_HCI_OP_REMOTE_NAME_REQUEST, sizeof(*cp));
304		if (!buf) {
305			return -ENOBUFS;
306		}
307	
308		cp = net_buf_add(buf, sizeof(*cp));
309	
310		bt_addr_copy(&cp->bdaddr, addr);
311		cp->pscan_rep_mode = pscan;
312		cp->reserved = 0x00; /* reserved, should be set to 0x00 */
313		cp->clock_offset = offset;
314	
315		return bt_hci_cmd_send_sync(hdev, BT_HCI_OP_REMOTE_NAME_REQUEST, buf, NULL);
316	}
317	
318	#define EIR_SHORT_NAME    0x08
319	#define EIR_COMPLETE_NAME 0x09
320	
321	static bool eir_has_name(const uint8_t *eir)
322	{
323		int len = 240;
324	
325		while (len) {
326			if (len < 2) {
327				break;
328			}
329	
330			/* Look for early termination */
331			if (!eir[0]) {
332				break;
333			}
334	
335			/* Check if field length is correct */
336			if (eir[0] > len - 1) {
337				break;
338			}
339	
340			switch (eir[1]) {
341			case EIR_SHORT_NAME:
342			case EIR_COMPLETE_NAME:
343				if (eir[0] > 1) {
344					return true;
345				}
346				break;
347			default:
348				break;
349			}
350	
351			/* Parse next AD Structure */
352			len -= eir[0] + 1;
353			eir += eir[0] + 1;
354		}
355	
356		return false;
357	}
