416	static struct bt_br_discovery_result *get_result_slot(struct bt_dev *hdev,
417										 const bt_addr_t *addr, int8_t rssi)
418	{
419		struct bt_br_discovery_result *result = NULL;
420		size_t i;
421	
422		/* check if already present in results */
423		for (i = 0; i < hdev->discovery_results_count; i++) {
424			if (bt_addr_eq(addr, &hdev->discovery_results[i].addr)) {
425				return &hdev->discovery_results[i];
426			}
427		}
428	
429		/* Pick a new slot (if available) */
430		if (hdev->discovery_results_count < hdev->discovery_results_size) {
431			bt_addr_copy(&hdev->discovery_results[hdev->discovery_results_count].addr, addr);
432			return &hdev->discovery_results[hdev->discovery_results_count++];
433		}
434	
435		/* ignore if invalid RSSI */
436		if (rssi == 0xff) {
437			return NULL;
438		}
439	
440		/*
441		 * Pick slot with smallest RSSI that is smaller then passed RSSI
442		 * TODO handle TX if present
443		 */
444		for (i = 0; i < hdev->discovery_results_size; i++) {
445			if (hdev->discovery_results[i].rssi > rssi) {
446				continue;
447			}
448	
449			if (!result || result->rssi > hdev->discovery_results[i].rssi) {
450				result = &hdev->discovery_results[i];
451			}
452		}
453	
454		if (result) {
455			LOG_DBG("Reusing slot (old %s rssi %d dBm)", bt_addr_str(&result->addr),
456				result->rssi);
457	
458			bt_addr_copy(&result->addr, addr);
459		}
460	
461		return result;
462	}
463	
464	static struct bt_br_discovery_result *find_discovery_result(struct bt_dev *hdev, const bt_addr_t *addr)
465	{
466		size_t i;
467	
468		/* check if already present in results */
469		for (i = 0; i < hdev->discovery_results_count; i++) {
470			if (!bt_addr_cmp(addr, &hdev->discovery_results[i].addr)) {
471				return &hdev->discovery_results[i];
472			}
473		}
474	
475		return NULL;
476	}
477	
478	void bt_hci_inquiry_result_with_rssi(struct bt_dev *hdev, struct net_buf *buf)
479	{
480		uint8_t num_reports = net_buf_pull_u8(buf);
481	
482		if (!atomic_test_bit(hdev->flags, BT_DEV_INQUIRY)) {
483			return;
484		}
485	
486		LOG_DBG("number of results: %u", num_reports);
487	
488		while (num_reports--) {
489			struct bt_hci_evt_inquiry_result_with_rssi *evt;
490			struct bt_br_discovery_result *result;
491			struct bt_br_discovery_priv *priv;
492			struct bt_br_discovery_cb *listener, *next;
493	
494			if (buf->len < sizeof(*evt)) {
495				LOG_ERR("Unexpected end to buffer");
496				return;
497			}
498	
499			evt = net_buf_pull_mem(buf, sizeof(*evt));
500			LOG_DBG("%s rssi %d dBm", bt_addr_str(&evt->addr), evt->rssi);
501	
502			result = get_result_slot(hdev, &evt->addr, evt->rssi);
503			if (!result) {
504				return;
505			}
506	
507			priv = &result->_priv;
508			priv->pscan_rep_mode = evt->pscan_rep_mode;
509			priv->clock_offset = evt->clock_offset;
510	
511			memcpy(result->cod, evt->cod, 3);
512			result->rssi = evt->rssi;
513	
514			/* we could reuse slot so make sure EIR is cleared */
515			(void)memset(result->eir, 0, sizeof(result->eir));
516	
517			SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&hdev->discovery_cbs, listener, next, node) {
518				if (listener->recv) {
519					listener->recv(result);
520				}
521			}
522		}
523	}
