525	void bt_hci_extended_inquiry_result(struct bt_dev *hdev, struct net_buf *buf)
526	{
527		struct bt_hci_evt_extended_inquiry_result *evt = (void *)buf->data;
528		struct bt_br_discovery_result *result;
529		struct bt_br_discovery_priv *priv;
530		struct bt_br_discovery_cb *listener, *next;
531	
532		if (!atomic_test_bit(hdev->flags, BT_DEV_INQUIRY)) {
533			return;
534		}
535	
536		LOG_DBG("%s rssi %d dBm", bt_addr_str(&evt->addr), evt->rssi);
537	
538		result = get_result_slot(hdev, &evt->addr, evt->rssi);
539		if (!result) {
540			return;
541		}
542	
543		priv = &result->_priv;
544		priv->pscan_rep_mode = evt->pscan_rep_mode;
545		priv->clock_offset = evt->clock_offset;
546	
547		result->rssi = evt->rssi;
548		memcpy(result->cod, evt->cod, 3);
549		memcpy(result->eir, evt->eir, sizeof(result->eir));
