700		uint16_t handle = sys_le16_to_cpu(evt->handle);
701		struct bt_conn *conn;
702	
703		LOG_DBG("status 0x%02x handle %u", evt->status, handle);
704	
705		conn = bt_conn_lookup_handle(hdev, handle, BT_CONN_TYPE_BR);
706		if (!conn) {
707			LOG_ERR("Can't find conn for handle %u", handle);
708			return;
709		}
710	
711		if (!evt->status && evt->page == 0x01) {
712			memcpy(conn->br.features[1], evt->features, sizeof(conn->br.features[1]));
713		}
714	
715		br_report_connection_state(conn);
716		bt_conn_unref(conn);
717	}
