774	static int read_ext_features(struct bt_dev *hdev)
775	{
776		int i;
777	
778		/* Read Local Supported Extended Features */
779		for (i = 1; i < LMP_FEAT_PAGES_COUNT; i++) {
780			struct bt_hci_cp_read_local_ext_features *cp;
781			struct bt_hci_rp_read_local_ext_features *rp;
782			struct net_buf *buf, *rsp;
783			int err;
784	
785			buf = bt_hci_cmd_create(BT_HCI_OP_READ_LOCAL_EXT_FEATURES, sizeof(*cp));
786			if (!buf) {
787				return -ENOBUFS;
788			}
789	
790			cp = net_buf_add(buf, sizeof(*cp));
791			cp->page = i;
792	
793			err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_READ_LOCAL_EXT_FEATURES, buf, &rsp);
794			if (err) {
795				return err;
796			}
797	
798			rp = (void *)rsp->data;
799	
800			memcpy(&hdev->features[i], rp->ext_features, sizeof(hdev->features[i]));
801	
802			if (rp->max_page <= i) {
803				net_buf_unref(rsp);
804				break;
805			}
806	
807			net_buf_unref(rsp);
808		}
809	
810		return 0;
811	}
