868	int bt_br_init(struct bt_dev *hdev)
869	{
870		struct net_buf *buf;
871		struct bt_hci_cp_write_ssp_mode *ssp_cp;
872		struct bt_hci_cp_write_inquiry_mode *inq_cp;
873		struct bt_hci_write_local_name *name_cp;
874		struct bt_hci_cp_write_class_of_device *cod;
875		struct bt_hci_cp_write_default_link_policy_settings *policy_cp;
876		int err;
877	
878		/* Read extended local features */
879		if (BT_FEAT_EXT_FEATURES(hdev->features)) {
880			err = read_ext_features(hdev);
881			if (err) {
882				return err;
883			}
884		}
885	
886		/* Add local supported packet types to bt_dev */
887		device_supported_pkt_type(hdev);
888	
889		/* Get BR/EDR buffer size */
890		err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_READ_BUFFER_SIZE, NULL, &buf);
891		if (err) {
892			return err;
893		}
894	
895		read_buffer_size_complete(hdev, buf);
896		net_buf_unref(buf);
897	
898		/* Set SSP mode */
899		buf = bt_hci_cmd_create(BT_HCI_OP_WRITE_SSP_MODE, sizeof(*ssp_cp));
900		if (!buf) {
901			return -ENOBUFS;
902		}
903	
904		ssp_cp = net_buf_add(buf, sizeof(*ssp_cp));
905		ssp_cp->mode = 0x01;
906		err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_WRITE_SSP_MODE, buf, NULL);
907		if (err) {
908			return err;
909		}
910	
911		/* Enable Inquiry results with RSSI or extended Inquiry */
912		buf = bt_hci_cmd_create(BT_HCI_OP_WRITE_INQUIRY_MODE, sizeof(*inq_cp));
913		if (!buf) {
914			return -ENOBUFS;
915		}
916	
917		inq_cp = net_buf_add(buf, sizeof(*inq_cp));
918		inq_cp->mode = 0x02;
919		err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_WRITE_INQUIRY_MODE, buf, NULL);
920		if (err) {
921			return err;
922		}
923	
924		/* Set local name */
925		buf = bt_hci_cmd_create(BT_HCI_OP_WRITE_LOCAL_NAME, sizeof(*name_cp));
926		if (!buf) {
927			return -ENOBUFS;
928		}
929	
930		name_cp = net_buf_add(buf, sizeof(*name_cp));
931		strncpy((char *)name_cp->local_name, CONFIG_BT_DEVICE_NAME, sizeof(name_cp->local_name));
932	
933		err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_WRITE_LOCAL_NAME, buf, NULL);
934		if (err) {
935			return err;
936		}
937	
938		/* Set Class of device */
939		buf = bt_hci_cmd_create(BT_HCI_OP_WRITE_CLASS_OF_DEVICE, sizeof(*cod));
940		if (!buf) {
941			return -ENOBUFS;
942		}
943	
944		net_buf_add_le24(buf, CONFIG_BT_COD);
945	
946		err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_WRITE_CLASS_OF_DEVICE, buf, NULL);
947		if (err) {
948			return err;
949		}
950	
951		/* Set page timeout*/
952		buf = bt_hci_cmd_create(BT_HCI_OP_WRITE_PAGE_TIMEOUT, sizeof(uint16_t));
953		if (!buf) {
954			return -ENOBUFS;
955		}
956	
957		net_buf_add_le16(buf, CONFIG_BT_PAGE_TIMEOUT);
958	
959		err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_WRITE_PAGE_TIMEOUT, buf, NULL);
960		if (err) {
961			return err;
962		}
963	
964		/* Enable BR/EDR SC if supported */
965		if (BT_FEAT_SC(hdev->features)) {
966			struct bt_hci_cp_write_sc_host_supp *sc_cp;
967	
968			buf = bt_hci_cmd_create(BT_HCI_OP_WRITE_SC_HOST_SUPP, sizeof(*sc_cp));
969			if (!buf) {
970				return -ENOBUFS;
971			}
972	
973			sc_cp = net_buf_add(buf, sizeof(*sc_cp));
974			sc_cp->sc_support = 0x01;
975	
976			err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_WRITE_SC_HOST_SUPP, buf, NULL);
977			if (err) {
978				return err;
979			}
980		}
981	
982		/* Set default link policy*/
983		buf = bt_hci_cmd_create(BT_HCI_OP_WRITE_DEFAULT_LINK_POLICY_SETTINGS, sizeof(*policy_cp));
984		if (!buf) {
985			return -ENOBUFS;
986		}
987	
988		policy_cp = net_buf_add(buf, sizeof(*policy_cp));
989		policy_cp->default_link_policy_settings =
990			BT_HCI_LINK_POLICY_SETTINGS_ENABLE_ROLE_SWITCH |
991			BT_HCI_LINK_POLICY_SETTINGS_ENABLE_HOLD_MODE |
992			BT_HCI_LINK_POLICY_SETTINGS_ENABLE_SNIFF_SWITCH;
993	
994		err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_WRITE_DEFAULT_LINK_POLICY_SETTINGS, buf, NULL);
995		if (err) {
996			return err;
997		}
998	
999		return 0;
1000	}
