1002	static int br_start_inquiry(struct bt_dev *hdev, const struct bt_br_discovery_param *param)
1003	{
1004		const uint8_t iac[3] = {0x33, 0x8b, 0x9e};
1005		struct bt_hci_op_inquiry *cp;
1006		struct net_buf *buf;
1007	
1008		buf = bt_hci_cmd_create(BT_HCI_OP_INQUIRY, sizeof(*cp));
1009		if (!buf) {
1010			return -ENOBUFS;
1011		}
1012	
1013		cp = net_buf_add(buf, sizeof(*cp));
1014	
1015		cp->length = param->length;
1016		cp->num_rsp = 0xff; /* we limit discovery only by time */
1017	
1018		memcpy(cp->lap, iac, 3);
1019		if (param->limited) {
1020			cp->lap[0] = 0x00;
1021		}
1022	
1023		return bt_hci_cmd_send_sync(hdev, BT_HCI_OP_INQUIRY, buf, NULL);
1024	}
