1149	static int write_scan_enable(struct bt_dev *hdev, uint8_t scan)
1150	{
1151		struct net_buf *buf;
1152		int err;
1153	
1154		LOG_DBG("type %u", scan);
1155	
1156		buf = bt_hci_cmd_create(BT_HCI_OP_WRITE_SCAN_ENABLE, 1);
1157		if (!buf) {
1158			return -ENOBUFS;
1159		}
1160	
1161		net_buf_add_u8(buf, scan);
1162		err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_WRITE_SCAN_ENABLE, buf, NULL);
1163		if (err) {
1164			return err;
1165		}
1166	
1167		atomic_set_bit_to(hdev->flags, BT_DEV_ISCAN, (scan & BT_BREDR_SCAN_INQUIRY));
1168		atomic_set_bit_to(hdev->flags, BT_DEV_PSCAN, (scan & BT_BREDR_SCAN_PAGE));
1169	
1170		return 0;
1171	}
