1173	int bt_br_set_connectable_mc(uint8_t dev_id, bool enable)
1174	{
1175		struct bt_dev *hdev;
1176	
1177		hdev = bt_dev_get(dev_id);
1178		if (!hdev) {
1179			return -ENODEV;
1180		}
1181	
1182		if (enable) {
1183			if (atomic_test_bit(hdev->flags, BT_DEV_PSCAN)) {
1184				return -EALREADY;
1185			} else {
1186				return write_scan_enable(hdev, BT_BREDR_SCAN_PAGE);
1187			}
1188		} else {
1189			if (!atomic_test_bit(hdev->flags, BT_DEV_PSCAN)) {
1190				return -EALREADY;
1191			} else {
1192				return write_scan_enable(hdev, BT_BREDR_SCAN_DISABLED);
1193			}
1194		}
