1225	int bt_br_set_visibility_mc(uint8_t dev_id, bool disc_mode, bool conn_mode)
1226	{
1227		uint8_t prev = BT_BREDR_SCAN_DISABLED;
1228		uint8_t next = BT_BREDR_SCAN_DISABLED;
1229		struct bt_dev *hdev;
1230	
1231		hdev = bt_dev_get(dev_id);
1232		if (!hdev) {
1233			return -ENODEV;
1234		}
1235	
1236		if (disc_mode && !conn_mode)
1237			return -EPERM;
1238	
1239		if (atomic_test_bit(hdev->flags, BT_DEV_PSCAN))
1240			prev |= BT_BREDR_SCAN_PAGE;
1241	
1242		if (atomic_test_bit(hdev->flags, BT_DEV_ISCAN))
1243			prev |= BT_BREDR_SCAN_INQUIRY;
1244	
1245		if (conn_mode)
1246			next |= BT_BREDR_SCAN_PAGE;
1247	
1248		if (disc_mode)
1249			next |= BT_BREDR_SCAN_INQUIRY;
1250	
1251		if (prev == next)
1252			return -EALREADY;
1253	
1254		return write_scan_enable(hdev, next);
1255	}
