1591		memcpy(&addr, bdaddr, sizeof(addr));
1592	
1593		SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&hdev->bt_auth_info_cbs, listener,
1594						  next, node) {
1595			if (listener->bond_deleted) {
1596				listener->bond_deleted(0, &addr);
1597			}
1598		}
1599	
1600		return 0;
